<div class="um-page" :aria-busy="loading">
    <div class="um-heading"><button class="um-primary" type="button" @click="startUserCreate()" :disabled="loading || !summary"><i data-lucide="user-round-plus" aria-hidden="true"></i>Create User</button></div>
    <div class="um-summary">
        @foreach ([['total', 'Total Users', 'users'], ['active', 'Active Users', 'user-round-check'], ['auditors', 'Auditors', 'clipboard-check'], ['auditees', 'Auditees', 'building-2']] as [$key, $label, $icon])
        <article data-summary="{{ $key }}"><div><span>{{ $label }}</span><strong x-text="summary?.{{ $key }} ?? '—'"></strong></div><i data-lucide="{{ $icon }}" aria-hidden="true"></i></article>
        @endforeach
    </div>
    <p x-page-notice="successPopupType" class="um-notice" role="status" x-show="successPopupVisible" x-cloak x-text="successPopupMessage"></p>
    <div class="um-filters">
        <label class="um-search">Search users<input type="search" x-model="search" @input.debounce.350ms="load(1)" maxlength="255" placeholder="Name, email or user code"></label>
        <label>Primary role<select x-model="filters.roleId" @change="load(1)"><option value="">All roles</option>@foreach ([0 => 'Super Admin', 1 => 'Admin', 2 => 'Auditor', 3 => 'Auditee'] as $id => $name)<option value="{{ $id }}">{{ $name }}</option>@endforeach</select></label>
        <label>Department / office<select x-model="filters.departmentId" @change="load(1)"><option value="">All departments / offices</option><template x-for="unit in options.departments" :key="unit._id"><option :value="unit._id" x-text="unit.name"></option></template></select></label>
        <label>Responsibility<select x-model="filters.responsibility" @change="load(1)"><option value="">All responsibilities</option><template x-for="responsibility in options.responsibilities" :key="responsibility"><option :value="responsibility" x-text="responsibilityName(responsibility)"></option></template></select></label>
        <label>Account status<select x-model="filters.status" @change="load(1)"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label>
        <button class="um-secondary" type="button" @click="clearUserFilters()">Clear filters</button>
    </div>
    <div class="um-loading" x-show="loading"><span class="sr-only" role="status">Loading users...</span><x-dashboard-skeleton type="table" :columns="7" /></div>
    <div x-page-notice class="um-error" role="alert" x-show="error" x-cloak><p x-text="error"></p><button class="um-secondary" type="button" @click="load()">Retry</button></div>
    <p class="um-empty" x-show="!loading && !error && rows.length === 0" x-cloak>No users match these filters. Try a different search or clear the filters.</p>
    <div class="um-table-wrap" x-show="!loading && !error && rows.length" x-cloak>
        <table class="um-table"><thead><tr><th>Full Name</th><th>Email</th><th>Primary Role</th><th>Organizational Responsibility</th><th>Assigned College / Department / Office</th><th>Account Status</th><th><span class="sr-only">Actions</span></th></tr></thead>
            <tbody><template x-for="row in rows" :key="row._id"><tr>
                <td data-label="Full Name"><strong x-text="row.fullName"></strong><small x-text="row.userCode || 'No user code recorded'"></small></td>
                <td data-label="Email" x-text="row.email"></td>
                <td data-label="Primary Role"><span class="um-role" :class="roleClass(row.roleId)" x-text="roleName(row.roleId)"></span><small x-show="row.isAuditTeamLeader">Audit Team Leader</small></td>
                <td data-label="Organizational Responsibility" x-text="responsibilityName(row.archiveResponsibility)"></td>
                <td data-label="Assigned Organization" x-text="assignmentNames(row)"></td>
                <td data-label="Account Status"><span class="um-status" :class="{'is-inactive': !row.isActive}" x-text="row.isActive ? 'Active' : 'Inactive'"></span></td>
                <td data-label="Actions"><button class="um-menu-trigger" type="button" @click="toggleUserMenu(row, $el)" aria-haspopup="menu" :aria-expanded="menuTarget?._id === row._id" :aria-label="`Actions for ${row.fullName}`"><span aria-hidden="true">&#8942;</span></button></td>
            </tr></template></tbody>
        </table>
    </div>
    <footer class="um-pagination" x-show="!loading && !error" x-cloak><span x-text="`${meta.total} matching users · Page ${page} of ${meta.lastPage}`"></span><label>Per page<select x-model.number="perPage" @change="load(1)"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option></select></label><div><button class="um-secondary" type="button" @click="load(page - 1)" :disabled="page <= 1 || loading">Previous</button><button class="um-secondary" type="button" @click="load(page + 1)" :disabled="page >= meta.lastPage || loading">Next</button></div></footer>
</div>
<div class="um-menu" x-ref="userMenu" popover="auto" role="menu" aria-label="User actions" @keydown="menuKey($event)" @toggle="if ($event.newState === 'closed') menuTarget = null">
    <button role="menuitem" type="button" @click="viewUser(menuTarget)">View details</button><button role="menuitem" type="button" @click="startUserEdit(menuTarget)">Edit user</button><button role="menuitem" type="button" @click="requestUserAction('reset', menuTarget)">Send password reset link</button>
    <button role="menuitem" type="button" x-show="menuTarget?.isActive" :disabled="!menuTarget?.canDeactivate || menuTarget?._id === @js((string) auth()->id())" @click="requestUserAction('deactivate', menuTarget)" class="um-danger">Deactivate account</button>
    <button role="menuitem" type="button" x-show="menuTarget && !menuTarget.isActive" @click="requestUserAction('reactivate', menuTarget)">Reactivate account</button>
</div>
<dialog class="um-dialog" x-ref="userEditor" aria-labelledby="um-editor-title" @cancel="if (saving) $event.preventDefault()">
    <form @submit.prevent="saveUser()">
        <header><div><span class="um-eyebrow">USER ACCOUNT</span><h2 id="um-editor-title" x-text="userForm._id ? 'Edit User' : 'Create User'"></h2><p>Account identity, organizational assignment and security.</p></div><button class="um-close" type="button" :disabled="saving" @click="$refs.userEditor.close()" aria-label="Close user editor">&#215;</button></header>
        <div class="um-dialog-body">
            <div x-page-notice class="um-error" role="alert" tabindex="-1" x-show="formError" x-cloak><p x-text="formError"></p><ul><template x-for="(errors, field) in fieldErrors" :key="field"><li x-text="errors.join(' ')"></li></template></ul></div>
            <fieldset :disabled="saving"><legend>Account Information</legend><div class="um-fields"><label>Full name<input x-model="userForm.fullName" required maxlength="255" autocomplete="name" :aria-invalid="!!fieldErrors.fullName"></label><label>Email address<input x-model="userForm.email" type="email" required maxlength="255" autocomplete="email" :aria-invalid="!!fieldErrors.email"></label></div><p x-show="originalUser?.userCode" x-text="`User code: ${originalUser?.userCode || ''}`"></p></fieldset>
            <fieldset :disabled="saving"><legend>Organizational Assignment</legend><div class="um-fields">
                <label>Organizational responsibility<select x-model="userForm.archiveResponsibility" @change="changeResponsibility()" :disabled="Number(userForm.roleId) === 2"><option value="">Not assigned</option><template x-for="responsibility in options.responsibilities" :key="responsibility"><option :value="responsibility" x-text="responsibilityName(responsibility)"></option></template></select></label>
                <label x-show="collegeResponsibility()">College<select x-model="userForm.archiveCollegeIds[0]" :required="collegeResponsibility()"><option value="">Choose a college</option><template x-for="college in options.colleges" :key="college._id"><option :value="college._id" x-text="college.name"></option></template></select></label>
                <label x-show="!collegeResponsibility() && ['department_head', 'department_secretary'].includes(userForm.archiveResponsibility)">Authorized CET department<select x-model="userForm.archiveUnitIds[0]" @change="userForm.departmentId = userForm.archiveUnitIds[0]" :required="['department_head', 'department_secretary'].includes(userForm.archiveResponsibility) && (!originalUser || originalUser.archiveResponsibility !== userForm.archiveResponsibility || originalUser.archiveUnitIds?.length)"><option value="">Choose one of the five CET departments</option><template x-for="unit in headUnits()" :key="unit._id"><option :value="unit._id" x-text="unit.name"></option></template></select></label>
                <label x-show="!collegeResponsibility() && !['department_head', 'department_secretary'].includes(userForm.archiveResponsibility)">Home department / office<select x-model="userForm.departmentId" :disabled="originalUser?.isAuditTeamLeader" :required="!collegeResponsibility() && Number(userForm.roleId) !== 0 && !['department_head', 'department_secretary'].includes(userForm.archiveResponsibility)"><option value="">Choose a department / office</option><template x-for="unit in availableUnits()" :key="unit._id"><option :value="unit._id" x-text="unit.name + (!unit.verified ? ' (legacy assignment)' : '')"></option></template></select></label>
                <label x-show="Number(userForm.roleId) === 3 && !collegeResponsibility()">Office / position name<input x-model="userForm.officeName" maxlength="255" :required="Number(userForm.roleId) === 3 && !userForm.archiveResponsibility" placeholder="Office or position"></label>
            </div><p x-show="collegeResponsibility()">College-level responsibilities apply to the selected college, not an individual department.</p><p x-show="Number(userForm.roleId) === 2">Auditors receive access only to explicitly assigned audits and permitted evidence.</p></fieldset>
            <fieldset :disabled="saving"><legend>Security and Permissions</legend><div class="um-fields">
                <label>Primary account role<select x-model.number="userForm.roleId" @change="changePrimaryRole()" :disabled="originalUser && (Number(originalUser.roleId) === 0 || originalUser.isAuditTeamLeader)" required>@foreach ([0 => 'Super Admin', 1 => 'Admin', 2 => 'Auditor', 3 => 'Auditee'] as $id => $name)<option :value="{{ $id }}">{{ $name }}</option>@endforeach</select></label>
                <label class="um-checkbox"><input type="checkbox" x-model="userForm.isActive" :disabled="originalUser && (!originalUser.canDeactivate || originalUser._id === @js((string) auth()->id())) || Number(userForm.roleId) === 0">Account is active</label>
            </div><div x-show="Number(userForm.roleId) === 2"><p>Eligible audit departments. These do not grant access to unassigned audits.</p><div class="um-check-grid"><template x-for="unit in options.departments.filter(unit => unit.authorizedCet)" :key="unit._id"><label class="um-checkbox"><input type="checkbox" x-model="userForm.assignedDepartmentIds" :value="unit._id"><span x-text="unit.name"></span></label></template></div></div>
            <p x-show="!userForm._id">A secure account setup link will be emailed. No existing credentials are changed.</p><p x-show="userForm._id">Passwords are managed through the existing password reset flow. Organizational responsibilities do not change the primary role.</p><p x-show="originalUser?.isAuditTeamLeader">This Admin is an Audit Team Leader. Its role and audit assignments are protected.</p></fieldset>
        </div><footer><button class="um-secondary" type="button" :disabled="saving" @click="$refs.userEditor.close()">Cancel</button><button class="um-primary" type="submit" :disabled="saving" x-text="saving ? 'Saving...' : (userForm._id ? 'Save changes' : 'Create User')"></button></footer>
    </form>
</dialog>
<dialog class="um-dialog" x-ref="userDetails" aria-labelledby="um-details-title" @close="detailRequest++">
    <header><div><span class="um-eyebrow">ACCOUNT OVERVIEW</span><h2 id="um-details-title">User Details</h2></div><button class="um-close" type="button" @click="$refs.userDetails.close()" aria-label="Close user details">&#215;</button></header>
    <div class="um-dialog-body" :aria-busy="detailLoading"><x-dashboard-skeleton type="activity" x-show="detailLoading" /><p x-page-notice class="um-error" role="alert" x-show="detailError" x-cloak x-text="detailError"></p>
        <template x-if="details"><div class="um-details-content">
            <section><h3>Account Information</h3><dl class="um-detail-grid">@foreach (['fullName' => 'Full name', 'email' => 'Email', 'userCode' => 'User code'] as $key => $label)<div><dt>{{ $label }}</dt><dd x-text="details.{{ $key }} || 'Not recorded'"></dd></div>@endforeach<div><dt>Primary role</dt><dd x-text="details.scope.primaryRole"></dd></div><div><dt>Account status</dt><dd x-text="details.isActive ? 'Active' : 'Inactive'"></dd></div><div><dt>Created</dt><dd x-text="userDate(details.createdAt || details.created_at)"></dd></div><div><dt>Last login</dt><dd x-text="userDate(details.lastLoginAt)"></dd></div><div><dt>Last updated</dt><dd x-text="userDate(details.updatedAt || details.updated_at)"></dd></div></dl></section>
            <section><h3>Organizational Responsibilities</h3><p x-text="responsibilityName(details.archiveResponsibility)"></p><p x-text="assignmentNames(details)"></p><p x-show="details.officeName" x-text="details.officeName"></p></section>
            <section><h3>Actual Access Scope</h3><p x-text="details.scope.policy"></p><p x-show="!details.scope.active">This account is inactive and cannot sign in.</p><dl class="um-detail-grid"><div><dt>Archive units in scope</dt><dd x-text="details.scope.archiveUnits.join(', ') || 'None'"></dd></div><div><dt>Accessible archive records</dt><dd x-text="details.scope.accessibleArchiveCount"></dd></div><div><dt>Assigned audits</dt><dd x-text="details.scope.assignedAudits.map(audit => audit.reference || audit.id).join(', ') || 'None'"></dd></div><div><dt>Audits assigned for ATL review</dt><dd x-text="details.scope.reviewAuditCount"></dd></div></dl><p>Document visibility and explicit evidence sharing are checked on every request. Role definitions do not override these rules.</p></section>
            <section><h3>Available Account Activity</h3><p x-show="!details.activity.length">No account activity has been recorded.</p><ol class="um-activity" tabindex="0" aria-label="Available account activity"><template x-for="(entry, index) in details.activity" :key="index"><li><strong x-text="entry.action"></strong><span x-text="entry.actor"></span><time x-text="userDate(entry.at)"></time></li></template></ol><p>Shows up to 20 recorded account actions and actions performed by this user.</p></section>
        </div></template>
    </div><footer><button class="um-secondary" type="button" @click="$refs.userDetails.close()">Close</button></footer>
</dialog>
<dialog class="um-dialog um-confirm" x-ref="userAction" aria-labelledby="um-action-title" @cancel="if (saving) $event.preventDefault()">
    <header><h2 id="um-action-title" x-text="action === 'reset' ? 'Send password reset link?' : action === 'deactivate' ? 'Deactivate account?' : 'Reactivate account?'"></h2></header><div class="um-dialog-body"><p x-text="actionTarget ? `${actionTarget.fullName} · ${actionTarget.email}` : ''"></p><p x-show="action === 'deactivate'">This user will lose access. Their records and relationships will be retained.</p><p x-show="action === 'reset'">Send a secure, time-limited link to the account email. The current password stays valid until the user completes the reset.</p><p x-page-notice class="um-error" role="alert" x-show="actionError" x-text="actionError"></p></div><footer><button class="um-secondary" type="button" :disabled="saving" @click="$refs.userAction.close()">Cancel</button><button class="um-primary" type="button" :disabled="saving" @click="confirmUserAction()" x-text="saving ? 'Working...' : 'Confirm'"></button></footer>
</dialog>
